const solicitud = $input.first().json;
const cabeceras = solicitud.headers ?? {};
const cuerpo = solicitud.body ?? {};
const tokenEsperado = $env.N8N_TOKEN_SECRETO ?? '';

function rechazar(codigoHttp, mensaje) {
  return [{ json: { valida: false, codigoHttp, respuesta: { estado: 'Error', mensaje } } }];
}

if (!tokenEsperado || cabeceras['x-token-secreto'] !== tokenEsperado) {
  return rechazar(401, 'Token no autorizado');
}

const descripcion = typeof cuerpo.descripcion === 'string' ? cuerpo.descripcion.trim() : '';
if (!descripcion) {
  return rechazar(400, 'La descripcion no puede estar vacia');
}

const limiteMinimo = Number($env.LIMITE_MINIMO_FUENTES ?? 3);
const limiteMaximo = Number($env.LIMITE_MAXIMO_FUENTES ?? 5);
const umbral = cuerpo.umbralSimilitud ?? Number($env.UMBRAL_SIMILITUD ?? 0.6);
const limite = cuerpo.limiteResultados ?? limiteMaximo;
const coleccion = cuerpo.coleccion ?? $env.QDRANT_COLECCION ?? 'articulosConocimiento';

if (typeof umbral !== 'number' || Number.isNaN(umbral) || umbral < 0 || umbral > 1) {
  return rechazar(400, 'umbralSimilitud debe ser un numero entre 0 y 1');
}
if (!Number.isInteger(limite) || limite < limiteMinimo || limite > limiteMaximo) {
  return rechazar(400, `limiteResultados debe ser un entero entre ${limiteMinimo} y ${limiteMaximo}`);
}
if (typeof coleccion !== 'string' || !/^[A-Za-z0-9_-]{1,64}$/.test(coleccion)) {
  return rechazar(400, 'coleccion tiene un nombre no valido');
}

return [{ json: { valida: true, descripcion, umbral, limite, limiteMinimo, coleccion } }];

const parametros = $('Validar solicitud').first().json;
const puntos = $input.first().json.result ?? [];

const resultados = puntos
  .map((punto) => ({
    idArticulo: punto.payload?.idArticulo ?? punto.id,
    titulo: punto.payload?.titulo ?? null,
    categoria: punto.payload?.categoria ?? null,
    similitud: Number(punto.score.toFixed(4)),
    problema: punto.payload?.problema ?? null,
    solucion: punto.payload?.solucion ?? null,
    fecha: punto.payload?.fecha ?? null,
  }))
  .sort((a, b) => b.similitud - a.similitud);

const respuesta = {
  estado: resultados.length > 0 ? 'Con resultados' : 'Sin resultados',
  umbralSimilitud: parametros.umbral,
  limiteResultados: parametros.limite,
  total: resultados.length,
  suficientes: resultados.length >= parametros.limiteMinimo,
  resultados,
};

if (resultados.length === 0) {
  respuesta.mensaje = 'No hay informacion suficiente';
}

return [{ json: { codigoHttp: 200, respuesta } }];

return [{
  json: {
    codigoHttp: 502,
    respuesta: { estado: 'Error', mensaje: 'El servicio de embeddings no esta disponible' },
  },
}];

const mensajeOrigen = String($input.first().json.error?.message ?? '');
const coleccionInexistente = /^\s*404\b/.test(mensajeOrigen);
const mensaje = coleccionInexistente
  ? 'La coleccion no existe. Ejecutar primero la indexacion de articulos'
  : 'La base vectorial no esta disponible';
return [{ json: { codigoHttp: 502, respuesta: { estado: 'Error', mensaje } } }];
